mapper.select:
SELECT r.*, IFNULL(st.reserved_count, 0) AS reservedCount, IFNULL(st.seated_count, 0) AS seatedCount, GREATEST(r.capacity - IFNULL(st.reserved_count, 0), 0) AS availableCount FROM study_room r LEFT JOIN ( SELECT sr.room_id, COUNT(DISTINCT sr.seat_id) AS reserved_count, SUM(CASE WHEN sr.status = 'SEATED' THEN 1 ELSE 0 END) AS seated_count FROM seat_reservation sr WHERE sr.reserve_date = #{today} AND sr.status IN ('WAITING', 'SEATED') GROUP BY sr.room_id ) st ON st.room_id = r.id
AND r.room_type = #{roomType}
AND r.status = #{status}
AND (r.name LIKE CONCAT('%', #{keyword}, '%') OR r.location LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.room_type DESC, r.id ASC
